/**
 * Bash Completion Template
 */

import { ShellScriptOptions } from "../types";

/**
 * Generate Bash completion script
 */
export function bashTemplate(options: ShellScriptOptions): string {
  const { binName } = options;

  return `# ${binName} completion script for Bash
# Generated by pontx completion:generate

_${binName}_completions() {
  local cur="\${COMP_WORDS[COMP_CWORD]}"
  local line="\${COMP_LINE}"

  # Call CLI to get completion suggestions
  local completions
  completions=$("${binName}" --get-completions "\$line" "\$COMP_CWORD" 2>/dev/null)

  if [[ $? -eq 0 ]]; then
    # Check if current word contains a dot (dotted path like spec.tag.api)
    if [[ "\$cur" == *.* ]]; then
      # For dotted paths, use completions directly without prefix matching
      # This replaces the entire current word
      COMPREPLY=(\$completions)
    else
      # Normal completion with prefix matching
      COMPREPLY=($(compgen -W "\$completions" -- "\$cur"))
    fi
  fi
}

complete -o nospace -F _${binName}_completions ${binName}
`;
}

/**
 * Get Bash installation instructions
 */
export function bashInstallInstructions(binName: string): string {
  return `# Add to ~/.bashrc or ~/.bash_profile:
eval "$(${binName} completion generate --shell=bash)"

# Or save to a file and source it:
${binName} completion generate --shell=bash > ~/.${binName}-completion.bash
echo 'source ~/.${binName}-completion.bash' >> ~/.bashrc
`;
}
